pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    v.iter().zip(p.iter()).all(|(vc, pc)| vc == pc)
}

pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|v| has_prefix(v, &p))
        .collect()
}